# Let me analyze each transformation step by step
inputs = ['ij', 'xhju', 'iwfvxy', 'dvw', 'dhwhu']
outputs = ['ij', 'xicju', 'iwyiuvxy', 'dvw', 'ddbicu']

print("Analyzing transformations:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"{inp} -> {out}")

print("\nDetailed character-by-character analysis:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"\n{i+1}. '{inp}' -> '{out}'")
    if inp != out:
        # Find differences
        min_len = min(len(inp), len(out))
        for j in range(min_len):
            if inp[j] != out[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{out[j]}'")
        if len(inp) != len(out):
            if len(inp) > len(out):
                print(f"  Extra chars removed at end: '{inp[len(out):]}'")
            else:
                print(f"  Extra chars added at end: '{out[len(inp):]}'")

